 建的按钮和输入框已经自动包过了，不用再包。

button.onClick.AddListener(new UnityAction(ctx.Guarded("点击发牌", OnDeal)));

example.code:
ctx.Log.Info("loaded v" + ctx.Version);
try { DoWork(); }
catch (Exception e) { ctx.Log.Error("DoWork 失败", e); }

ISubscription _tick;

public override void OnLoad(ModContext ctx)
{
    ctx.MainThread.Delay(2.0f, SayLater);
    _tick = ctx.MainThread.EveryFrame(EachFrame);
}

void SayLater() { Context.Log.Info("2 秒到了"); }
void EachFrame() { if (_finished) _tick.Cancel(); }

// 提供方 mod 的 OnLoad（GreeterService 定义在提供方 DLL 里）
ctx.Services.Register<GreeterService>(new GreeterService());

// 使用方 mod：用到时再取，提供方没加载或已停用时拿不到
GreeterService greeter;
if (Context.Services.TryGet<GreeterService>(out greeter)) greeter.Greet("hi");

public override void OnLoad(ModContext ctx)
{
    ctx.Events.OnRoundStarted(OnRound);
}

void OnRound(int round)
{
    Context.Log.Info("round " + round.ToString(CultureInfo.InvariantCulture));
}

int runs = ctx.Data.Get<int>("runs", 0);
ctx.Data.Set("runs", runs + 1);
if (ctx.Data.Has("legacyKey")) ctx.Data.Remove("legacyKey");

public override void OnLoad(ModContext ctx)
{
    bool ok = ctx.Input.RegisterHotkey("greet", "Ctrl+F8", Greet);
    if (!ok) ctx.Log.Warn("Ctrl+F8 被占用了，请在管理器里给 greet 换一个键");
}

void Greet() { Context.Log.Info("hi"); }

member.example:
一个最小的 mod：

public sealed class ModMain : YxMod
{
    ConfigEntry<int> _count;

    public override void OnLoad(ModContext ctx)
    {
        _count = ctx.Config.Bind("general", "count", 3, "问候次数");
        ctx.Input.RegisterHotkey("greet", "F8", Greet);
        ctx.Log.Info("loaded v" + ctx.Version);
    }

    void Greet()
    {
        Context.Log.Info("hello x" + _count.Value.ToString(CultureInfo.InvariantCulture));
    }
}

member.summary:
一组要么一起生效、要么就别用的钩子。 找不到方法会抛异常——在 OnLoad 里没接住，整个 mod 就加载失败；
而游戏一更新，某个方法改名是常事。用一组来装：哪个没挂上只记一条 warn、记进 ，不抛；
装完看  决定功能开不开（比如「离线保护的钩子不全就禁止进练习场」）。

HookGroup offline = ctx.Hooks.Group("离线保护");
offline.Prefix("CardPanel", "MoveToGrid", 2, OnMove);
offline.Postfix("CardPanel", "MoveToGrid", 2, OnMoved);
if (!offline.Complete) ctx.Log.Warn("功能已关闭，没挂上：" + offline.Missing);

停用 / 热重载时组里的钩子和其它钩子一样由宿主自动解除。只在主线程用。

在一个游戏（热更）方法的入口挂处理器：能读改参数（）、能跳过原方法（）。
处理器在原方法的调用线程上执行（目前验证过的都是主线程）；处理器里抛的异常由宿主接住并计入错误预算，原方法照常执行。
停用 / 热重载时自动解除。实机：PASS（03f H01–H14）。用法与限制见 docs/dev/hooks.md。

ctx.Hooks.Prefix("CardPanel", "MoveToGrid", 2, h =>
{
    ctx.Log.Info("要把牌放到第 " + ((int)h.Args[1]).ToString(CultureInfo.InvariantCulture) + " 格");
    return true;            // true = 继续执行原方法
});
